service.method:

		INSERT INTO UPUSH
		(
			  CODE
			, ADD_DATE
			, ADD_TIME
			, ADD_USER_ID
			, CHANGE_DATE
			, CHANGE_TIME
			, CHANGE_USER_ID
			, DESCRIPTION
			, DEL_FLAG          
		)
        VALUES
		(
			  ${CODE}
			, ${current.DATE}
			, ${current.TIME}
			, ${session.ID}
			, ${current.DATE}
			, ${current.TIME}
			, ${session.ID}
			, ${DESCRIPTION}
			, 'N'
		)


UPDATE UPUSH
   SET CHANGE_DATE    = ${current.DATE} 
     , CHANGE_TIME    = ${current.TIME}
     , CHANGE_USER_ID = ${session.ID}
     , DESCRIPTION    = #DB_OWNER#NVL(${DESCRIPTION}, DESCRIPTION)
     , DEL_FLAG       = #DB_OWNER#NVL(${DEL_FLAG}   , DEL_FLAG)
 WHERE CODE           = ${CODE}


INSERT INTO UPUSO
(
	  HOUSE_CODE
	, CODE
	, TYPE
	, OPTION_NAME
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
	, CHANGE_USER_ID
	, OPTION_VALUE
)
VALUES
(
	  '000'
	, ${CODE}
	, ${TYPE}
	, ${OPTION_NAME}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${OPTION_VALUE}
)


DELETE FROM
	UPUSO
WHERE
	HOUSE_CODE 	= '000'
AND CODE       	= ${CODE}
AND TYPE		= ${TYPE}
AND OPTION_NAME = ${OPTION_NAME}


UPDATE
	UPUSH
SET
	DEL_FLAG = ${DEL_FLAG} 
WHERE
	CODE = ${CODE}


    	INSERT INTO UPUSH_HISTORY
		(
			  HISTORY_KEY
			, ACTION_MODE
			, CODE
			, DESCRIPTION
			, DEL_FLAG
			, ADD_USER_ID
			, ADD_DATE
			, ADD_TIME
		)
		VALUES
		(
			  ${HISTORY_KEY}
			, ${ACTION_MODE}
			, ${CODE}
			, ${DESCRIPTION}
			, ${DEL_FLAG}
			, ${session.ID}
			, ${current.DATE}
			, ${current.TIME}
		)


    	INSERT INTO upuso_history
		(
			  HISTORY_KEY
			, ACTION_MODE
			, HOUSE_CODE
			, CODE
			, TYPE
			, OPTION_NAME
			, OPTION_VALUE
			, ADD_USER_ID
			, ADD_DATE
			, ADD_TIME
		)
		VALUES
		(
			  ${HISTORY_KEY}
			, ${ACTION_MODE}
			, '000'
			, ${CODE}
			, ${TYPE}
			, ${OPTION_NAME}
			, ${OPTION_VALUE}
			, ${session.ID}
			, ${current.DATE}
			, ${current.TIME}
		)
